mod my_game {
  pub type Player {
    name: Str;
    score: Int;
    level: Int;
  }

  pub fn create_player(name: Str) -> Player {
    Player{ name: name, score: 0, level: 1 }
  }

  pub fn complete_level(p: &mut Player) {
    p.level += 1;
    p.score += p.level * 100;
  }

  pub fn display_status(p: &Player) {
    io.println(p.name);
    io.println(p.score);
    io.println(p.level);
  }
}

fn main() -> Int {
  use my_game;
  let mut player = my_game.create_player("Adventurer");
  my_game.complete_level(&mut player);
  my_game.complete_level(&mut player);
  my_game.display_status(&player);
  return 0;
}
